1: /**
2:  * Entry point: listen, and close cleanly.
3:  *
4:  * `startServer` is what the tests use (ephemeral port, no process side effects) and
5:  * `main` is the thin wrapper that reads the environment and installs the signal
6:  * handlers. Nothing here participates in the booking guarantee.
7:  */
8: 
9: import { createServer, type Server } from 'node:http';
10: import { createRequestListener } from './routes.ts';
11: import { openDatabase, type Db, type TxOptions } from './db.ts';
12: 
13: export type StartedServer = {
14:   server: Server;
15:   db: Db;
16:   port: number;
17:   close: () => Promise<void>;
18: };
19: 
20: export type StartOptions = {
21:   /** Defaults to 0, so a test never fights the machine for a port. */
22:   port?: number;
23:   host?: string;
24:   busyTimeoutMs?: number;
25:   /** Lets the busy-path test shrink the retry budget; production uses the defaults. */
26:   txOptions?: TxOptions;
27: };
28: 
29: export function startServer(databasePath: string, options: StartOptions = {}): Promise<StartedServer> {
30:   const port = options.port ?? 0;
31:   const host = options.host ?? '127.0.0.1';
32:   const db = openDatabase(databasePath, { busyTimeoutMs: options.busyTimeoutMs });
33: 
34:   return new Promise<StartedServer>((resolve, reject) => {
35:     const server = createServer(createRequestListener(db, options.txOptions ?? {}));
36:     server.on('error', (err) => {
37:       db.close();
38:       reject(err);
39:     });
40:     server.listen(port, host, () => {
41:       const address = server.address();
42:       if (address === null || typeof address === 'string') {
43:         server.close();
44:         db.close();
45:         reject(new Error('server did not bind to a TCP port'));
46:         return;
47:       }
48:       resolve({
49:         server,
50:         db,
51:         port: address.port,
52:         close: () =>
53:           new Promise<void>((done, fail) => {
54:             server.close((err) => {
55:               db.close();
56:               if (err) fail(err);
57:               else done();
58:             });
59:             server.closeAllConnections();
60:           }),
61:       });
62:     });
63:   });
64: }
65: 
66: async function main(): Promise<void> {
67:   const databasePath = process.env.TABLEKEEPER_DB ?? 'tablekeeper.db';
68:   const port = Number(process.env.PORT ?? 3000);
69:   const started = await startServer(databasePath, { port });
70:   process.stdout.write(`tablekeeper stage-1 listening on http://127.0.0.1:${started.port}\n`);
71: 
72:   let closing = false;
73:   const shutdown = (): void => {
74:     if (closing) return;
75:     closing = true;
76:     void started.close().then(
77:       () => process.exit(0),
78:       () => process.exit(1),
79:     );
80:   };
81:   process.on('SIGINT', shutdown);
82:   process.on('SIGTERM', shutdown);
83: }
84: 
85: if (process.argv[1] !== undefined && import.meta.url === new URL(`file://${process.argv[1]}`).href) {
86:   await main();
87: }

