30: function describe(value: unknown): string {
31:   if (value === undefined) return 'absent';
32:   if (value === null) return 'null';
33:   if (Array.isArray(value)) return 'array';
34:   if (typeof value === 'object') return 'object';
35:   if (typeof value === 'string') return value.length > 120 ? `${value.slice(0, 120)}…` : value;
36:   return String(value);
