41: function readBody(req: import('node:http').IncomingMessage): Promise<Buffer> {
42:   return new Promise((resolve, reject) => {
43:     const chunks: Buffer[] = [];
44:     let size = 0;
45:     let oversize: { size: number } | undefined;
46:     let settled = false;
47:     const settle = (run: () => void): void => {
48:       if (settled) return;
49:       settled = true;
50:       run();
51:     };
52: 
53:     req.on('data', (chunk: Buffer) => {
54:       size += chunk.length;
55:       if (oversize !== undefined) {
56:         // Already refusing this body. Keep reading only so the request can finish and
57:         // the response can be delivered; nothing more is kept in memory.
58:         if (size > DRAIN_LIMIT_BYTES) {
59:           // The caller is not going to stop. There is no response worth delivering to a
60:           // peer sending this much, so give up on the socket rather than read forever.
61:           settle(() => reject(badBody('body', `request body exceeds ${MAX_BODY_BYTES} bytes`, size)));
62:           req.destroy();
63:         }
64:         return;
65:       }
66:       if (size > MAX_BODY_BYTES) {
67:         // Stop accumulating, but do not destroy the socket: destroying here kills the
68:         // connection before the 400 envelope written by the route handler can reach the
69:         // client, which then reports a transport TypeError instead of a refusal it can
70:         // read. Draining to 'end' is what lets the answer arrive.
71:         oversize = { size };
72:         chunks.length = 0;
73:         return;
74:       }
75:       chunks.push(chunk);
76:     });
77:     req.on('end', () => {
78:       if (oversize !== undefined) {
79:         settle(() => reject(badBody('body', `request body exceeds ${MAX_BODY_BYTES} bytes`, oversize!.size)));
80:         return;
81:       }
82:       settle(() => resolve(Buffer.concat(chunks)));
83:     });
84:     req.on('error', (err) => settle(() => reject(err)));
85:     req.on('aborted', () => settle(() => reject(badBody('body', 'request aborted before the body was complete', undefined))));
86:   });
