268: export function cancelBooking(db: Db, bookingId: string, txOptions: TxOptions = {}): void {
269:   const id = requireText(bookingId, 'booking_id', 'NOT_FOUND');
270:   inImmediateTransaction(
271:     db,
272:     () => {
273:       const row = db.prepare('SELECT id, status FROM booking WHERE id = ?').get(id) as
274:         | { id: string; status: string }
275:         | undefined;
276:       if (row === undefined || row.id === undefined || row.status !== 'confirmed') {
277:         throw new ApiError('NOT_FOUND', 'no confirmed booking with that id', { booking_id: id });
278:       }
279:       db.prepare('DELETE FROM occupancy WHERE booking_id = ?').run(id);
280:       db.prepare("UPDATE booking SET status = 'cancelled' WHERE id = ?").run(id);
