1: /**
2:  * The error taxonomy and its HTTP mapping.
3:  *
4:  * Every non-2xx response in this service is one of these codes. A code is not a
5:  * free-form string: it carries a fixed status here, so a caller can branch on
6:  * `error.code` and a reviewer can enumerate the whole surface from one map.
7:  */
8: 
9: export const ERROR_STATUS = {
10:   INVALID_TIME: 400,
11:   AMBIGUOUS_LOCAL_TIME: 400,
12:   INVALID_TIMEZONE: 400,
13:   INVALID_PARTY_SIZE: 400,
14:   INVALID_DURATION: 400,
15:   INVALID_TABLE: 400,
16:   SLOT_TAKEN: 409,
17:   TABLE_TOO_SMALL: 409,
18:   KEY_REUSED: 409,
19:   NOT_FOUND: 404,
20:   BUSY_RETRY_EXHAUSTED: 503,
21:   /**
22:    * The catch-all. Present in the taxonomy rather than cast in at the throw site, so the
23:    * whole failure surface stays enumerable from one map and `ErrorCode` cannot disagree
24:    * with what a caller is actually sent.
25:    */
26:   INTERNAL: 500,
27: } as const;
28: 
29: export type ErrorCode = keyof typeof ERROR_STATUS;
30: 
31: export type ErrorDetails = Record<string, unknown>;
32: 
33: export class ApiError extends Error {
34:   readonly code: ErrorCode;
35:   readonly details: ErrorDetails;
36: 
37:   constructor(code: ErrorCode, message: string, details: ErrorDetails = {}) {
38:     super(message);
39:     this.name = 'ApiError';
40:     this.code = code;
41:     this.details = details;
42:   }
43: 
44:   get status(): number {
45:     return ERROR_STATUS[this.code];
46:   }
47: 
48:   toEnvelope(): { status: number; body: { error: { code: ErrorCode; message: string; details: ErrorDetails } } } {
49:     return {
50:       status: this.status,
51:       body: { error: { code: this.code, message: this.message, details: this.details } },
52:     };
53:   }
54: }
55: 
56: export function isApiError(value: unknown): value is ApiError {
57:   return value instanceof ApiError;
58: }
59: 
60: // SQLite primary result codes meaning "another writer holds the lock". node:sqlite
61: // exposes these as the numeric `errcode`; its own `code` is always the generic
62: // 'ERR_SQLITE_ERROR', so matching on `code` would classify every constraint failure
63: // as contention.
64: const SQLITE_BUSY = 5;
65: const SQLITE_LOCKED = 6;
66: const SQLITE_BUSY_RECOVERY = 261;
67: const SQLITE_BUSY_SNAPSHOT = 517;
68: const SQLITE_BUSY_TIMEOUT = 773;
69: const BUSY_CODES: ReadonlySet<number> = new Set([
70:   SQLITE_BUSY,
71:   SQLITE_LOCKED,
72:   SQLITE_BUSY_RECOVERY,
73:   SQLITE_BUSY_SNAPSHOT,
74:   SQLITE_BUSY_TIMEOUT,
75: ]);
76: 
77: /** True for the SQLite errors that mean "a writer held the lock; try again". */
78: export function isBusyError(err: unknown): boolean {
79:   const errcode = (err as { errcode?: unknown } | null)?.errcode;
80:   return typeof errcode === 'number' && BUSY_CODES.has(errcode);
81: }
82: 
83: /**
84:  * True for a primary-key violation on `occupancy` — a genuine double-book attempt.
85:  *
86:  * Deliberately narrow: a CHECK or FOREIGN KEY failure on the same table is a
87:  * different defect and must not be reported to a caller as "the slot is taken".
88:  */
89: export function isOccupancyKeyViolation(err: unknown): boolean {
90:   const message = (err as { message?: unknown } | null)?.message;
91:   return (
92:     typeof message === 'string' &&
93:     message.startsWith('UNIQUE constraint failed: occupancy.dining_table_id, occupancy.quantum_start_utc')
94:   );
95: }
96: 
97: /**
98:  * Turn anything thrown into the single response shape. An unrecognised throw is
99:  * reported as `NOT_FOUND` only when it really is a lookup miss; anything else is a
100:  * 500 with a generic message, because leaking an internal message to a caller is
101:  * worse than being vague.
102:  */
103: export function toErrorResponse(err: unknown): {
104:   status: number;
105:   body: { error: { code: ErrorCode; message: string; details: ErrorDetails } };
106: } {
107:   // Every branch returns an ApiError envelope, so the code here is a real member of
108:   // ErrorCode and the taxonomy test in test/http.test.ts can require it to be reachable.
109:   if (isApiError(err)) return err.toEnvelope();
110:   if (isBusyError(err)) {
111:     return new ApiError(
112:       'BUSY_RETRY_EXHAUSTED',
113:       'the booking store is busy; the request may be retried',
114:       { retryable: true },
115:     ).toEnvelope();
116:   }
117:   return new ApiError('INTERNAL', 'the request could not be completed').toEnvelope();
118: }

