1: /**
2:  * Stage 4 Static Server and Proxy
3:  *
4:  * Serves static files from the frontend directory and proxies API requests
5:  * to the backend service.
6:  */
7: 
8: import { createServer } from 'node:http';
9: import { readFile } from 'node:fs/promises';
10: import { join, resolve, extname } from 'node:path';
11: 
12: export const DEFAULT_BACKEND_URL = 'http://127.0.0.1:3000';
13: 
14: const MIME_TYPES = {
15:   '.html': 'text/html',
16:   '.js': 'application/javascript',
17:   '.css': 'text/css',
18:   '.json': 'application/json',
19:   '.png': 'image/png',
20:   '.jpg': 'image/jpeg',
21:   '.gif': 'image/gif',
22:   '.svg': 'image/svg+xml',
23:   '.ico': 'image/x-icon',
24: };
25: 
26: /**
27:  * @typedef {Object} ServerOptions
28:  * @property {number} [port=8080]
29:  * @property {string} [host='127.0.0.1']
30:  * @property {string} [backendUrl]
31:  */
32: 
33: /**
34:  * @typedef {Object} ServerInstance
35:  * @property {import('node:http').Server} server
36:  * @property {number} port
37:  * @property {() => Promise<void>} close
38:  */
39: 
40: /**
41:  * Start the Stage 4 static server and proxy.
42:  *
43:  * @param {string} frontendDir - Directory containing static files
44:  * @param {ServerOptions} options
45:  * @returns {Promise<ServerInstance>}
46:  */
47: export async function startServer(frontendDir, options = {}) {
48:   const port = options.port ?? 8080;
49:   const host = options.host ?? '127.0.0.1';
50:   const backendUrl = options.backendUrl ?? DEFAULT_BACKEND_URL;
51: 
52:   const server = createServer(async (req, res) => {
53:     const method = req.method ?? 'GET';
54:     let pathname;
55: 
56:     try {
57:       pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
58:     } catch {
59:       sendError(res, 400, 'BAD_REQUEST', 'Invalid URL');
60:       return;
61:     }
62: 
63:     // Block path traversal attempts
64:     const normalizedPath = resolve(join(frontendDir, pathname));
65:     if (!normalizedPath.startsWith(frontendDir)) {
66:       sendError(res, 404, 'NOT_FOUND', 'Not found');
67:       return;
68:     }
69: 
70:     // API routes go to backend
71:     if (pathname.startsWith('/v1/') || pathname === '/health') {
72:       await proxyToBackend(backendUrl, req, res, pathname);
73:       return;
74:     }
75: 
76:     // Static file serving
77:     await serveStatic(frontendDir, pathname, res);
78:   });
79: 
80:   return new Promise((resolve, reject) => {
81:     server.on('error', reject);
82:     server.listen(port, host, () => {
83:       const address = server.address();
84:       resolve({
85:         server,
86:         port: typeof address === 'object' ? address.port : port,
87:         close: () => new Promise((done, fail) => {
88:           server.close((err) => {
89:             if (err) fail(err);
90:             else done();
91:           });
92:           server.closeAllConnections();
93:         }),
94:       });
95:     });
96:   });
97: }
98: 
99: /**
100:  * Serve a static file from the frontend directory.
101:  *
102:  * @param {string} frontendDir
103:  * @param {string} pathname
104:  * @param {import('node:http').ServerResponse} res
105:  */
106: async function serveStatic(frontendDir, pathname, res) {
107:   // Default to index.html for root
108:   const filePath = pathname === '/' || pathname === ''
109:     ? join(frontendDir, 'index.html')
110:     : join(frontendDir, pathname);
111: 
112:   try {
113:     const content = await readFile(filePath);
114:     const ext = extname(filePath);
115:     const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
116: 
117:     res.writeHead(200, {
118:       'content-type': `${mimeType}; charset=utf-8`,
119:       'content-length': content.length,
120:     });
121:     res.end(content);
122:   } catch (err) {
123:     if (err.code === 'ENOENT') {
124:       sendError(res, 404, 'NOT_FOUND', 'Not found');
125:     } else {
126:       sendError(res, 500, 'INTERNAL', 'Internal server error');
127:     }
128:   }
129: }
130: 
131: /**
132:  * Proxy a request to the backend.
133:  *
134:  * @param {string} backendUrl
135:  * @param {import('node:http').IncomingMessage} req
136:  * @param {import('node:http').ServerResponse} res
137:  * @param {string} pathname
138:  */
139: async function proxyToBackend(backendUrl, req, res, pathname) {
140:   const method = req.method ?? 'GET';
141: 
142:   // Collect request body for proxied requests with body
143:   let body = Buffer.alloc(0);
144:   if (method === 'POST' || method === 'PUT' || method === 'PATCH') {
145:     body = await collectBody(req);
146:   }
147: 
148:   const targetUrl = `${backendUrl}${pathname}${req.url?.includes('?') ? '?' + req.url.split('?')[1] : ''}`;
149: 
150:   try {
151:     const fetchOptions = {
152:       method,
153:       headers: {
154:         'content-type': req.headers['content-type'] ?? 'application/json',
155:       },
156:     };
157: 
158:     if (body.length > 0) {
159:       fetchOptions.body = body;
160:     }
161: 
162:     const backendRes = await fetch(targetUrl, fetchOptions);
163: 
164:     // Forward response headers and body
165:     res.writeHead(backendRes.status, {
166:       'content-type': backendRes.headers.get('content-type') ?? 'application/json',
167:     });
168: 
169:     const backendBody = await backendRes.text();
170:     res.end(backendBody);
171:   } catch (err) {
172:     // Backend unavailable - return deterministic 5xx JSON error
173:     sendError(res, 503, 'SERVICE_UNAVAILABLE', 'Backend service unavailable');
174:   }
175: }
176: 
177: /**
178:  * Collect the request body into a buffer.
179:  *
180:  * @param {import('node:http').IncomingMessage} req
181:  * @returns {Promise<Buffer>}
182:  */
183: function collectBody(req) {
184:   return new Promise((resolve, reject) => {
185:     const chunks = [];
186:     req.on('data', chunk => chunks.push(chunk));
187:     req.on('end', () => resolve(Buffer.concat(chunks)));
188:     req.on('error', reject);
189:   });
190: }
191: 
192: /**
193:  * Send a JSON error response.
194:  *
195:  * @param {import('node:http').ServerResponse} res
196:  * @param {number} status
197:  * @param {string} code
198:  * @param {string} message
199:  */
200: function sendError(res, status, code, message) {
201:   const body = JSON.stringify({ error: { code, message } });
202:   res.writeHead(status, {
203:     'content-type': 'application/json; charset=utf-8',
204:     'content-length': Buffer.byteLength(body),
205:   });
206:   res.end(body);
207: }
