 */
async function handleCancelBooking() {
  if (!currentBooking) {
    showBookingDetails('No booking loaded.', 'error');
    return;
  }

  showBookingDetails('Cancelling booking...', 'loading');
  hideCancelSection();

  const result = await apiRequest(`/v1/bookings/${encodeURIComponent(currentBooking.id)}`, {
    method: 'DELETE',
  });

  if (result.ok) {
    currentBooking = null;
    saveContext();

    elements.bookingDetails.innerHTML = `
      <div class="message success">
        <strong>Booking cancelled successfully.</strong>
        <p>The booking has been cancelled and is no longer active.</p>
      </div>
