    showBookingDetails(`Error: ${message} (${result.error?.code})`, 'error');
    showCancelSection();
  }
}

/**
 * Update context display
 */
function updateContextDisplay() {
  if (!elements.contextSummary) return;

  const hasContext = currentRestaurant || currentTables.length > 0 || currentBooking;

  if (hasContext) {
    elements.contextSummary.style.display = 'block';
    elements.contextRestaurant.textContent = currentRestaurant
      ? `${currentRestaurant.name} (${currentRestaurant.id})`
      : 'None';
    elements.contextTables.textContent = currentTables.length > 0
      ? currentTables.map(t => `${t.id} (${t.seats} seats)`).join(', ')
      : 'None';

    // Also show table setup card if we have a restaurant
    if (currentRestaurant) {
      elements.tableSetupCard.style.display = 'block';
      updateTablesList();
    }
  } else {
    elements.contextSummary.style.display = 'none';
    elements.tableSetupCard.style.display = 'none';
  }
}

/**
 * Save context to sessionStorage
 */
function saveContext() {
  try {
    const context = {
      restaurant: currentRestaurant,
      tables: currentTables,
      booking: currentBooking,
    };
    sessionStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(context));
  } catch {
    // Ignore storage errors
  }
}

/**
 * Load context from sessionStorage
 */
function loadContext() {
  try {
    const stored = sessionStorage.getItem(SESSION_STORAGE_KEY);
    if (stored) {
      const context = JSON.parse(stored);
      currentRestaurant = context.restaurant || null;
      currentTables = context.tables || [];
      currentBooking = context.booking || null;
    }
  } catch {
    // Ignore storage errors
  }
}

/**
 * Clear all context
 */
function clearContext() {
  currentRestaurant = null;
  currentTables = [];
  currentBooking = null;
  selectedSlot = null;

  try {
    sessionStorage.removeItem(SESSION_STORAGE_KEY);
  } catch {
    // Ignore storage errors
  }

  updateContextDisplay();
  clearBookingForm();
  showStatus('Context cleared.', 'info');
}

/**
 * Escape HTML entities
 */
function escapeHtml(text) {
  if (typeof text !== 'string') return String(text);
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// Initialize when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
