{"name": "write", "args": {"content": "/**
 * Unit 6 — Manage and Cancellation Flow (RED tests, TDD order).
 *
 * - Loads and renders a booking
 * - Handles NOT_FOUND
 * - Requires an in-page cancel confirmation (never window.confirm)
 * - Treats DELETE 204 as success
 * - Repeated cancellation visibly reports the backend's NOT_FOUND
 */

import { describe, it, before, after } from 'node:test';
import assert from 'node:assert';
import {
  startRealBackend,
  createUi,
  submit,
  click,
  quickDemo,
  waitFor,
  seedHours,
  futureDate,
} from './helpers/ui.mjs';

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

describe('Unit 6: Manage and Cancellation Flow', () => {
  let backend;
  let ui;
  let demo;
  let booked;

  before(async () => {
    backend = await startRealBackend();
    ui = await createUi(backend.baseUrl);
    demo = await quickDemo(ui);
    seedHours(backend.db, demo.restaurant);

    // Create a real booking directly through the API so the manage tests are
    // independent of the booking UI flow covered in Unit 5.
    const response = await fetch(`${backend.baseUrl}/v1/bookings`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        restaurant_id: demo.restaurant,
        table_ids: [demo.tables[0]],
        party_size: 2,
        local_start: `${futureDate()}T12:00`,
        duration_min: 60,
        idempotency_key: undefined,
        fold: null,
      }),
    });
    assert.strictEqual(response.status, 201);
    booked = (await response.json()).id;
  });

  after(async () => {
    ui?.close();
    await backend?.close();
  });

  function retrieve(id) {
    const { window, document } = ui;
    document.getElementById('manage-booking-id').value = id;
    submit(window, document.getElementById('manage-form'));
  }

  it('loads and renders every BookingView field', async () => {
    const { document } = ui;
    retrieve(booked);

    const details = await waitFor(() => document.querySelector('#booking-details .detail-list'), {
      label: 'booking details rendered',
    });
    const text = details.textContent;
    assert.strictEqual(document.getElementById('detail-booking-id').textContent, booked);
    assert.match(text, new RegExp(booked), 'booking id');
    assert.match(text, new RegExp(demo.restaurant), 'restaurant_id');
    assert.match(text, /2/, 'party_size');
    assert.match(text, /T\d{2}:\d{2}/, 'start_utc');
    assert.match(text, /60 minutes/, 'duration_min');
    assert.match(text, /confirmed/, 'status');
    assert.match(text, /T\d{2}:\d{2}/, 'created_at_utc');
  });

  it('handles NOT_FOUND and hides the cancel action', async () => {
    const { document } = ui;
    retrieve('00000000-0000-4000-8000-000000000000');

    const error = await waitFor(() => document.querySelector('#booking-details .message.error'), {
      label: 'NOT_FOUND error',
    });
    assert.match(error.textContent, /\[NOT_FOUND\]/);
    assert.strictEqual(document.getElementById('cancel-section').style.display, 'none');
  });

  it('requires an in-page confirmation before DELETE and never uses window.confirm', async () => {
    const { window, document, fetchLog } = ui;

    let confirmCalls = 0;
    const originalConfirm = window.confirm;
    window.confirm = () => {
      confirmCalls += 1;
      return true;
    };

    retrieve(booked);
    await waitFor(() => document.getElementById('cancel-section').style.display !== 'none', {
      label: 'cancel block shown after load',
    });

    const deletesBefore = fetchLog.filter((e) => e.method === 'DELETE').length;
    assert.strictEqual(deletesBefore, 0, 'loading a booking never sends DELETE');

    // The cancellation only happens once the user clicks the in-page confirm.
    click(window, document.getElementById('confirm-cancel-btn'));
    await waitFor(() => document.querySelector('#booking-details .message.success'), {
      label: 'cancel success',
    });

    assert.strictEqual(confirmCalls, 0, 'window.confirm must not be used');
    window.confirm = originalConfirm;
  });

  it('treats HTTP 204 from DELETE as success and marks the booking inactive', async () => {
    const { document, fetchLog } = ui;
    const deleteEntry = fetchLog.find((e) => e.method === 'DELETE');
    assert.ok(deleteEntry, 'a DELETE was issued');
    assert.strictEqual(deleteEntry.status, 204, 'the backend answered 204');

    const success = document.querySelector('#booking-details .message.success');
    assert.match(success.textContent, /cancelled/i);
    assert.match(success.textContent, new RegExp(booked), 'names the booking that was cancelled');
  });

  it('reports NOT_FOUND again when the cancelled booking is cancelled a second time', async () => {
    const { window, document } = ui;

    // Retrieving an already-cancelled booking still returns it.
    retrieve(booked);
    await waitFor(
      () => document.querySelector('#booking-details .status-badge.cancelled') !== null,
      { label: 'cancelled status rendered on reload' },
    );

    // The cancel block is available again; confirming it must fail with NOT_FOUND.
    click(window, document.getElementById('confirm-cancel-btn'));
    const error = await waitFor(
      () => document.querySelector('#booking-details .message.error') !== null,
      { label: 'second cancellation error' },
    );
    assert.match(error.textContent, new RegExp(booked), 'the same booking id is in the message');
    assert.match(error.textContent, /\[NOT_FOUND\]/, 'repeated cancellation is visibly refused');
  });
});", "filePath": "C:\Users\deba3\band-work\result\stage-4\test\ui-manage.test.mjs"}, "tool_call_id": "call_42a1dec3d3ac409186541066"}

{"name": "write", "args": {"content": "/**
 * Unit 7 — Responsive / Accessibility (RED checks, TDD order).
 *
 * - Every input has a programmatic label and an error association
 * - All actions are keyboard operable (native controls, no trap tabindex)
 * - Status has visible semantics, state is never conveyed by color alone
 * - A narrow viewport has no horizontal overflow (layout verified in E2E;
 *   this unit pins the responsive rule that makes it pass)
 */

import { describe, it, before, after } from 'node:test';
import assert from 'node:assert';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { JSDOM } from 'jsdom';
import { startRealBackend, createUi, ROOT_DIR, FRONTEND_DIR } from './helpers/ui.mjs';

describe('Unit 7: Responsive and Accessibility', () => {
  let backend;
  let ui;

  before(async () => {
    backend = await startRealBackend();
    ui = await createUi(backend.baseUrl);
  });

  after(async () => {
    ui?.close();
    await backend?.close();
  });

  it('gives every form control a programmatic label', () => {
    const { document } = ui;
    const controls = [...document.querySelectorAll('input, select, textarea')];
    assert.ok(controls.length >= 8, `expected several controls, found ${controls.length}`);

    for (const control of controls) {
      const hasLabelFor = Boolean(
        control.id && document.querySelector(`label[for="${CSS.escape(control.id)}"]`),
      );
      assert.ok(
        hasLabelFor,
        `control #${control.id} (${
          control.name ?? '?'
        }) must have a label[for] pointing at it`,
      );
    }
  });

  it('associates error regions with inputs via aria-describedby', () => {
    const { document } = ui;
    const described = [...document.querySelectorAll('input[aria-describedby], select[aria-describedby]')];
    assert.ok(described.length >= 6, `have error associations on ${described.length} controls`);

    for (const control of described) {
      const ids = control.getAttribute('aria-describedby').split(/\s+/);
      for (const id of ids) {
        const referenced = document.getElementById(id);
        assert.ok(
          referenced !== null,
          `#${control.id} describes #${id} which must exist`,
        );
        assert.ok(
          referenced.classList.contains('form-error') || referenced.classList.contains('help-text'),
          `#${id} should be an error or help region`,
        );
      }
    }

    // The actual error regions are role=alert so a change is announced.
    const alerts = document.querySelectorAll('[role="alert"]');
    assert.ok(alerts.length >= 4, 'each form has a live alert region');
  });

  it('keeps every action on native, keyboard-reachable elements', () => {
    const { document } = ui;
    const buttons = [...document.querySelectorAll('button')];
    assert.ok(buttons.length >= 8, 'interactive actions are real buttons');
    for (const button of buttons) {
      assert.ok(
        button.textContent.trim() !== '' || button.getAttribute('aria-label'),
        'every button has an accessible name',
      );
    }

    const hasPositiveTabIndex = [...document.querySelectorAll('[tabindex]')].some(
      (el) => Number(el.getAttribute('tabindex')) > 0,
    );
    assert.strictEqual(hasPositiveTabIndex, false, 'no positive tabindex traps');

    // No clickable div/span pretending to be a button.
    const fakeButtons = [...document.querySelectorAll('div[role="button"], span[onclick], div[onclick]')];
    assert.strictEqual(fakeButtons.length, 0, 'no synthetic click targets');
  });

  it('exposes status with visible semantics, not color alone', () => {
    const { document } = ui;

    // One shared aria-live region for async results.
    const live = document.querySelectorAll('#global-status[aria-live="polite"]');
    assert.strictEqual(live.length, 1, 'one global live region');

    const statusRegions = document.querySelectorAll('.connection-status[role="status"], .result, .search-results, .booking-result, .booking-details');
    assert.ok(statusRegions.length >= 3, 'async result containers are documented regions');

    // Connection state carries a text label beside any color.
    const statusText = document.querySelector('#connection-status .status-text');
    assert.ok(statusText, 'connection status has a text label');

    // Navigation marks the current page, not just colors it.
    const activeNav = document.querySelector('.nav-btn[aria-current="page"]');
    assert.ok(activeNav, 'active nav has aria-current');
  });

  it('uses one h1 and semantic section headings', () => {
    const { document } = ui;
    assert.strictEqual(document.querySelectorAll('h1').length, 1, 'exactly one h1');
    const sectionHeadings = [...document.querySelectorAll('section > h2')];
    assert.strictEqual(sectionHeadings.length, 4, 'each section opens with an h2');
  });

  it('pins a responsive rule so a narrow viewport cannot overflow horizontally', async () => {
    const css = await readFile(join(FRONTEND_DIR, 'styles.css'), 'utf8');
    assert.match(css, /@media\s*\(max-width:\s*640px\)/, 'has a narrow-viewport media query');
    assert.match(css, /overflow-wrap:\s*anywhere/, 'long ids/URLs wrap instead of overflowing');
    assert.match(css, /body\s*\{[^}]*overflow-wrap:\s*anywhere/, 'the body cannot widen the page');
  });
});

describe('Unit 7: static HTML audit', () => {
  it('has no script tags with remote sources and no external CDN links', async () => {
    const html = await readFile(join(FRONTEND_DIR, 'index.html'), 'utf8');
    assert.doesNotMatch(html, /src="https?:|href="https?:/, 'no external resources');
  });

  it('declares lang and viewport for readers and narrow screens', async () => {
    const html = await readFile(join(FRONTEND_DIR, 'index.html'), 'utf8');
    assert.match(html, /<html lang="en">/);
    assert.match(html, /name="viewport"/);
  });
