367: /* ------------------------------------------------------------------ *
368:  * Time zone fold resolution
369:  *
370:  * The backend resolves local_start to one UTC instant; when a wall time
371:  * occurs twice (fall-back) it demands fold 0 (earlier) or 1 (later).
372:  * The slot the user picked carries its exact start_utc, so the fold is
373:  * computed here by reproducing the backend's candidate scan.
374:  * ------------------------------------------------------------------ */
375: 
376: function wallClockAt(ms, timezone) {
377:   const parts = new Intl.DateTimeFormat('en-US', {
378:     timeZone: timezone,
379:     year: 'numeric',
380:     month: '2-digit',
381:     day: '2-digit',
382:     hour: '2-digit',
383:     minute: '2-digit',
384:     hourCycle: 'h23',
385:   }).formatToParts(new Date(ms));
386:   const read = (type) => {
387:     const part = parts.find((candidate) => candidate.type === type);
388:     return part === undefined ? Number.NaN : Number(part.value);
389:   };
390:   return {
391:     year: read('year'),
392:     month: read('month'),
393:     day: read('day'),
394:     hour: read('hour'),
395:     minute: read('minute'),
396:   };
397: }
