427:  * start_utc, or undefined when it cannot be determined locally.
428:  */
429: function computeFold(localStart, timezone, selectedUtc) {
430:   if (!timezone || !selectedUtc) return undefined;
431:   const candidates = findLocalStartCandidates(localStart, timezone);
432:   if (candidates.length < 2) return undefined;
