{"name": "write", "args": {"content": "/**
 * Debug wrapper (temporary) used to discover why a Playwright webServer child
 * exits early on Windows. Logs lifecycle + child stderr to a file.
 */
const { spawn } = require('node:child_process');
const fs = require('node:fs');

const LOG = process.env.WS_MARKER_LOG;
const append = (line) => {
  try {
    fs.appendFileSync(LOG, `${new Date().toISOString()} ${line}\n`);
  } catch {}
};

append('marker starting, argv=' + process.argv.slice(2).join(' '));
const child = spawn(process.execPath, process.argv.slice(2), {
  cwd: process.env.WS_CWD,
  env: process.env,
  stdio: ['ignore', 'pipe', 'pipe'],
});
append('spawned pid=' + child.pid);
child.stdout.on('data', (d) => append('[out] ' + d.toString().trim()));
child.stderr.on('data', (d) => append('[err] ' + d.toString().trim()));
child.on('error', (e) => append('error: ' + e.message));
child.on('exit', (code, signal) => append(`exit code=${code} signal=${signal}`));

for (const sig of ['SIGTERM', 'SIGINT']) {
  process.on(sig, () => {
    append('marker got ' + sig);
    child.kill(sig);
  });
}
process.on('disconnect', () => {
  append('marker parent disconnected');
  if (child.exitCode === null) child.kill('SIGTERM');
});", "filePath": "C:\Users\deba3\band-work\result\stage-4\test\e2e\spawn-marker.cjs"}, "tool_call_id": "call_4363d0f1202e4fe4ae5f11fc"}

