23:   const yyyy = date.getUTCFullYear();
24:   const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
25:   const dd = String(date.getUTCDate()).padStart(2, '0');
26:   return `${yyyy}-${mm}-${dd}`;
27: }
