30:  * Create a restaurant and two tables through the real API, then open it for
31:  * every weekday (06:00-23:00 local) by writing restaurant_hours directly.
32:  */
33: export async function seedRestaurant(apiBase = FRONTEND_BASE) {
34:   const restaurantResponse = await fetch(`${apiBase}/v1/restaurants`, {
35:     method: 'POST',
36:     headers: { 'content-type': 'application/json' },
37:     body: JSON.stringify({ name: `E2E Diner ${Date.now()}`, timezone: 'America/New_York' }),
38:   });
39:   if (!restaurantResponse.ok) {
40:     throw new Error(`seeding restaurant failed: ${restaurantResponse.status}`);
41:   }
