53:   });
54:   const smallId = (await small.json()).id;
55:   const largeId = (await large.json()).id;
56: 
57:   const db = new DatabaseSync(E2E_DB);
58:   for (let weekday = 0; weekday <= 6; weekday += 1) {
59:     db.exec(
60:       `INSERT INTO restaurant_hours (restaurant_id, weekday, opens_min, closes_min)
61:        VALUES ('${restaurantId}', ${weekday}, 360, 1380)`,
62:     );
63:   }
64:   db.close();
