16: async function fillSearch(page, restaurantId, { date, partySize = 2, duration = 60 } = {}) {
17:   await page.getByRole('button', { name: /search/i }).click();
18:   await page.fill('#search-restaurant-id', restaurantId);
19:   await page.fill('#search-date', date ?? futureLocalDate());
20:   await page.fill('#search-party-size', String(partySize));
21:   await page.fill('#search-duration', String(duration));
22:   await page.click('#search-form button[type="submit"]');
23: }
24: 
25: async function searchAndPick(page, restaurantId, options) {
26:   await fillSearch(page, restaurantId, options);
27:   await expect(page.locator('.slot-card').first()).toBeVisible({ timeout: 10_000 });
28:   await page.locator('.slot-card .select-slot-btn').first().click();
29:   await expect(page.locator('#section-book')).toHaveClass(/active/);
30: }
31: 
32: async function confirmBooking(page) {
33:   await page.click('#booking-form button[type="submit"]');
34:   await expect(page.locator('#booking-result .message.success')).toBeVisible({ timeout: 10_000 });
35:   const id = (await page.locator('#new-booking-id').textContent()) ?? '';
36:   expect(id).toMatch(UUID_RE);
37:   return id;
38: }
39: 
40: test.describe('TableKeeper Stage 4 end to end', () => {
41:   let seeded;
42: 
43:   test.beforeAll(async () => {
44:     seeded = await seedRestaurant();
45:   });
46: 
47:   test('happy path: search, book, verify, cancel', async ({ page }) => {
48:     await page.goto('/');
49:     await expect(page.locator('#connection-status')).toHaveClass(/connected/);
50: 
51:     await searchAndPick(page, seeded.restaurantId);
52:     const bookingId = await confirmBooking(page);
53: 
54:     // Verify in Manage...
55:     await page.locator('#booking-result .go-manage-btn').click();
56:     await expect(page.locator('#section-manage')).toHaveClass(/active/);
57:     await expect(page.locator('#manage-booking-id')).toHaveValue(bookingId);
58:     await page.click('#manage-form button[type="submit"]');
59:     await expect(page.locator('#detail-booking-id')).toHaveText(bookingId);
60:     await expect(page.locator('#booking-details .status-badge')).toHaveText(/confirmed/i);
61: 
62:     // ...then cancel with an in-page confirmation.
63:     await expect(page.locator('#cancel-section')).toHaveCSS('display', 'block');
64:     await page.click('#confirm-cancel-btn');
65:     await expect(page.locator('#booking-details .message.success')).toContainText(/cancelled/i);
66:   });
67: 
68:   test('a slot already taken is refused and never shown as a success', async ({ browser }) => {
69:     const contextA = await browser.newContext();
70:     const contextB = await browser.newContext();
71:     const pageA = await contextA.newPage();
72:     const pageB = await contextB.newPage();
73: 
74:     // Both pages load the same slot list before anyone books.
75:     await pageA.goto('/');
76:     await pageB.goto('/');
77:     await searchAndPick(pageA, seeded.restaurantId);
78:     await searchAndPick(pageB, seeded.restaurantId);
