138:  * @param {string} pathname
139:  */
140: async function proxyToBackend(backendUrl, req, res, pathname) {
141:   const method = req.method ?? 'GET';
142: 
143:   // Collect request body for proxied requests with body
144:   let body = Buffer.alloc(0);
145:   if (method === 'POST' || method === 'PUT' || method === 'PATCH') {
146:     body = await collectBody(req);
147:   }
148: 
149:   const targetUrl = `${backendUrl}${pathname}${req.url?.includes('?') ? '?' + req.url.split('?')[1] : ''}`;
150: 
151:   try {
152:     const fetchOptions = {
153:       method,
154:       headers: {
155:         'content-type': req.headers['content-type'] ?? 'application/json',
156:       },
157:     };
158: 
159:     if (body.length > 0) {
160:       fetchOptions.body = body;
161:     }
162: 
163:     const backendRes = await fetch(targetUrl, fetchOptions);
164: 
165:     // Forward response headers and body
166:     res.writeHead(backendRes.status, {
167:       'content-type': backendRes.headers.get('content-type') ?? 'application/json',
168:     });
169: 
170:     const backendBody = await backendRes.text();
171:     res.end(backendBody);
172:   } catch (err) {
173:     // Backend unavailable - return deterministic 5xx JSON error
174:     sendError(res, 503, 'SERVICE_UNAVAILABLE', 'Backend service unavailable');
175:   }
176: }
