178: /**
179:  * Collect the request body into a buffer.
180:  *
181:  * @param {import('node:http').IncomingMessage} req
182:  * @returns {Promise<Buffer>}
183:  */
184: function collectBody(req) {
185:   return new Promise((resolve, reject) => {
186:     const chunks = [];
187:     req.on('data', chunk => chunks.push(chunk));
188:     req.on('end', () => resolve(Buffer.concat(chunks)));
189:     req.on('error', reject);
190:   });
191: }
