199:  * @param {string} message
200:  */
201: function sendError(res, status, code, message) {
202:   const body = JSON.stringify({ error: { code, message } });
203:   res.writeHead(status, {
204:     'content-type': 'application/json; charset=utf-8',
205:     'content-length': Buffer.byteLength(body),
206:   });
