64:     await page.click('#confirm-cancel-btn');
65:     await expect(page.locator('#booking-details .message.success')).toContainText(/cancelled/i);
66:   });
67: 
68:   test('a slot already taken is refused and never shown as a success', async ({ browser }) => {
69:     const contextA = await browser.newContext();
70:     const contextB = await browser.newContext();
71:     const pageA = await contextA.newPage();
72:     const pageB = await contextB.newPage();
73: 
74:     // Both pages load the same slot list before anyone books.
75:     await pageA.goto('/');
76:     await pageB.goto('/');
