1: /**
2:  * Shared harness for the Units 3-7 UI tests.
3:  *
4:  * Boots the REAL composed backend (stage 1 routes + stage 2 availability) on
5:  * an ephemeral port with a disposable SQLite file, then loads the canonical
6:  * index.html + app.js into jsdom pointed at that server. Every test therefore
7:  * exercises the actual product code with no fixture writes into frontend/.
8:  */
9: 
10: import { createServer } from 'node:http';
11: import { readFile, rm } from 'node:fs/promises';
12: import { tmpdir } from 'node:os';
13: import { join, dirname } from 'node:path';
14: import { fileURLToPath } from 'node:url';
15: import { randomUUID } from 'node:crypto';
16: import { JSDOM } from 'jsdom';
