18: const here = dirname(fileURLToPath(import.meta.url));
19: export const ROOT_DIR = join(here, '..', '..');
20: export const FRONTEND_DIR = join(ROOT_DIR, 'frontend');
21: 
22: /**
23:  * Start the composed backend (stage 1 + stage 2 listener) on an ephemeral port.
24:  * Returns the port, the open Db handle (for direct fixture seeding), the db path
25:  * and a close() that tears everything down and removes the disposable files.
26:  */
27: export async function startRealBackend() {
28:   const { openDatabase } = await import('../../../stage-1/src/db.ts');
29:   const { createStage2RequestListener } = await import('../../../stage-2/src/availability.ts');
30:   const { migrate2 } = await import('../../../stage-2/src/hours.ts');
31: 
32:   const dbPath = join(tmpdir(), `tablekeeper-ui-${randomUUID()}.db`);
33:   const db = openDatabase(dbPath);
34:   migrate2(db);
35: 
36:   const server = createServer(createStage2RequestListener(db));
37:   await new Promise((resolve, reject) => {
38:     server.once('error', reject);
39:     server.listen(0, '127.0.0.1', resolve);
40:   });
41:   const port = server.address().port;
42: 
43:   return {
44:     port,
45:     baseUrl: `http://127.0.0.1:${port}`,
46:     db,
47:     dbPath,
48:     async close() {
49:       await new Promise((resolve) => server.close(resolve));
50:       db.close();
51:       await rm(dbPath, { force: true });
52:       await rm(`${dbPath}-wal`, { force: true });
53:       await rm(`${dbPath}-shm`, { force: true });
54:     },
55:   };
56: }
