58: /**
59:  * Give a restaurant service hours for every weekday so availability searches
60:  * return real slots. Stages 1-2 expose no hours API (frozen scope), so tests
61:  * seed the disposable database directly, exactly as stage 2's own tests do.
62:  */
63: export function seedHours(db, restaurantId, opensMin = 6 * 60, closesMin = 23 * 60) {
64:   const stmt = db.prepare(
65:     'INSERT OR REPLACE INTO restaurant_hours (restaurant_id, weekday, opens_min, closes_min) VALUES (?, ?, ?, ?)',
66:   );
67:   for (let weekday = 0; weekday <= 6; weekday += 1) {
68:     stmt.run(restaurantId, weekday, opensMin, closesMin);
69:   }
70: }
