73:  * A minimal stand-in backend for states the real backend cannot be forced
74:  * into on demand (malformed bodies, forced failures, error envelopes).
75:  * routes: [{ match: (req) => bool, status, body, raw, delayMs }]
76:  */
77: export async function startStubBackend(routes) {
78:   const requests = [];
79:   const server = createServer((req, res) => {
80:     let body = '';
81:     req.on('data', (chunk) => {
82:       body += chunk;
83:     });
84:     req.on('end', () => {
85:       requests.push({ method: req.method, url: req.url, body });
86:       const route = routes.find((candidate) => candidate.match(req));
87:       const send = () => {
88:         if (!route) {
89:           res.writeHead(404, { 'content-type': 'application/json' });
90:           res.end(JSON.stringify({ error: { code: 'NOT_FOUND', message: 'stub: no route' } }));
91:           return;
92:         }
93:         if (route.status === undefined) {
94:           res.writeHead(204);
95:           res.end();
96:           return;
97:         }
98:         res.writeHead(route.status, { 'content-type': route.contentType ?? 'application/json' });
99:         res.end(route.raw ?? JSON.stringify(route.body));
100:       };
101:       if (route?.delayMs) setTimeout(send, route.delayMs);
102:       else send();
103:     });
104:   });
105:   await new Promise((resolve, reject) => {
106:     server.once('error', reject);
107:     server.listen(0, '127.0.0.1', resolve);
108:   });
109:   const port = server.address().port;
110:   return {
111:     port,
112:     baseUrl: `http://127.0.0.1:${port}`,
113:     requests,
114:     async close() {
115:       await new Promise((resolve) => server.close(resolve));
116:     },
117:   };
118: }
