120: /**
121:  * Load the canonical index.html + app.js into jsdom against `baseUrl`.
122:  *
123:  * Returns { window, document, fetchLog, close } where fetchLog records every
124:  * request the UI issued as { method, url, body } in order, which is what the
125:  * tests assert ordering and exact payloads against.
126:  */
127: export async function createUi(baseUrl) {
128:   const html = await readFile(join(FRONTEND_DIR, 'index.html'), 'utf8');
129:   const appSource = await readFile(join(FRONTEND_DIR, 'app.js'), 'utf8');
130: 
131:   const dom = new JSDOM(html, {
132:     url: `${baseUrl}/`,
133:     runScripts: 'outside-only',
134:     pretendToBeVisual: true,
135:   });
136:   const win = dom.window;
137: 
138:   const fetchLog = [];
139:   const realFetch = (...args) => globalThis.fetch(...args);
140:   win.fetch = async (input, init = {}) => {
141:     const url = typeof input === 'string' ? new URL(input, baseUrl) : new URL(input.url ?? input);
142:     let body = init.body;
143:     if (body !== undefined && typeof body !== 'string') body = String(body);
144:     const response = await realFetch(url, init);
145:     fetchLog.push({
146:       method: init.method ?? 'GET',
147:       url: url.pathname + url.search,
148:       body,
149:       status: response.status,
150:     });
151:     return response;
152:   };
153: 
154:   if (typeof win.crypto?.randomUUID !== 'function') {
155:     Object.defineProperty(win, 'crypto', {
156:       value: { randomUUID: () => globalThis.crypto.randomUUID(), getRandomValues: (a) => globalThis.crypto.getRandomValues(a) },
157:       configurable: true,
158:     });
159:   }
160: 
161:   // jsdom has no matchMedia; app.js does not use it, but keep it defined.
162:   if (typeof win.matchMedia !== 'function') {
163:     win.matchMedia = () => ({ matches: false, addListener() {}, removeListener() {} });
164:   }
165: 
166:   win.eval(appSource);
167: 
168:   // init() runs on DOMContentLoaded (or immediately if parsing already finished);
169:   // its first action is marking the connection status as "checking".
170:   await waitFor(
171:     () => {
172:       const status = win.document.getElementById('connection-status');
173:       return (
174:         status !== null &&
175:         (status.classList.contains('checking') ||
176:           status.classList.contains('connected') ||
177:           status.classList.contains('unavailable'))
178:       );
179:     },
180:     { label: 'app init (connection status marked)' },
181:   );
182:   // Let the initial /health probe settle.
183:   await tick(win, 30);
184: 
185:   return {
186:     window: win,
187:     document: win.document,
188:     fetchLog,
189:     close() {
190:       win.close();
191:     },
192:   };
193: }
