202: /**
203:  * Poll `fn` until it returns a truthy value or the timeout expires.
204:  */
205: export async function waitFor(fn, { timeout = 5000, interval = 15, label = 'condition' } = {}) {
206:   const start = Date.now();
207:   let lastError;
208:   for (;;) {
