23: 
24: function delay(ms) {
25:   return new Promise((resolve) => setTimeout(resolve, ms));
26: }
27: 
28: async function waitFor(fn, { timeout = 15000, interval = 150, label = 'condition' } = {}) {
29:   const start = Date.now();
30:   for (;;) {
31:     const value = await fn();
32:     if (value) return value;
33:     if (Date.now() - start > timeout) {
34:       throw new Error(`Timed out waiting for ${label}`);
35:     }
36:     await delay(interval);
37:   }
38: }
39: 
40: function freePort() {
41:   return new Promise((resolve, reject) => {
42:     const srv = createServer();
43:     srv.listen(0, '127.0.0.1', () => {
44:       const port = srv.address().port;
45:       srv.close(() => resolve(port));
46:     });
47:     srv.on('error', reject);
48:   });
49: }
50: 
51: function httpHealthy(port) {
52:   return fetch(`http://127.0.0.1:${port}/health`)
53:     .then((res) => res.ok)
54:     .catch(() => false);
55: }
56: 
57: async function waitPortsClosed(ports, timeout = 15000) {
58:   await waitFor(
59:     async () => {
60:       const states = await Promise.all(ports.map((port) => httpHealthy(port)));
61:       return states.every((ok) => !ok);
62:     },
63:     { timeout, label: `ports ${ports.join(',')} released` },
64:   );
65: }
