1: /**
2:  * Stage 4 Static Server and Proxy
3:  *
4:  * Serves static files from the frontend directory and proxies API requests
5:  * to the backend service.
6:  */
7: 
8: import { createServer } from 'node:http';
9: import { readFile } from 'node:fs/promises';
10: import { join, resolve, extname } from 'node:path';
11: import { fileURLToPath } from 'node:url';
12: 
13: export const DEFAULT_BACKEND_URL = 'http://127.0.0.1:3000';
14: 
15: const MIME_TYPES = {
16:   '.html': 'text/html',
17:   '.js': 'application/javascript',
18:   '.css': 'text/css',
19:   '.json': 'application/json',
20:   '.png': 'image/png',
21:   '.jpg': 'image/jpeg',
22:   '.gif': 'image/gif',
23:   '.svg': 'image/svg+xml',
24:   '.ico': 'image/x-icon',
25: };
26: 
27: /**
28:  * @typedef {Object} ServerOptions
29:  * @property {number} [port=8080]
30:  * @property {string} [host='127.0.0.1']
31:  * @property {string} [backendUrl]
32:  */
33: 
34: /**
35:  * @typedef {Object} ServerInstance
36:  * @property {import('node:http').Server} server
37:  * @property {number} port
38:  * @property {() => Promise<void>} close
39:  */
40: 
41: /**
42:  * Start the Stage 4 static server and proxy.
43:  *
44:  * @param {string} frontendDir - Directory containing static files
45:  * @param {ServerOptions} options
46:  * @returns {Promise<ServerInstance>}
47:  */
48: export async function startServer(frontendDir, options = {}) {
49:   const port = options.port ?? 8080;
50:   const host = options.host ?? '127.0.0.1';
51:   const backendUrl = options.backendUrl ?? DEFAULT_BACKEND_URL;
52: 
53:   const server = createServer(async (req, res) => {
54:     const method = req.method ?? 'GET';
55:     let pathname;
56: 
57:     try {
58:       pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
59:     } catch {
60:       sendError(res, 400, 'BAD_REQUEST', 'Invalid URL');
61:       return;
62:     }
63: 
64:     // Block path traversal attempts
65:     const normalizedPath = resolve(join(frontendDir, pathname));
66:     if (!normalizedPath.startsWith(frontendDir)) {
67:       sendError(res, 404, 'NOT_FOUND', 'Not found');
68:       return;
69:     }
70: 
71:     // API routes go to backend
72:     if (pathname.startsWith('/v1/') || pathname === '/health') {
73:       await proxyToBackend(backendUrl, req, res, pathname);
74:       return;
75:     }
76: 
77:     // Static file serving
78:     await serveStatic(frontendDir, pathname, res);
79:   });
80: 
81:   return new Promise((resolve, reject) => {
82:     server.on('error', reject);
83:     server.listen(port, host, () => {
84:       const address = server.address();
85:       resolve({
86:         server,
87:         port: typeof address === 'object' ? address.port : port,
88:         close: () => new Promise((done, fail) => {
89:           server.close((err) => {
90:             if (err) fail(err);
91:             else done();
92:           });
93:           server.closeAllConnections();
94:         }),
95:       });
96:     });
97:   });
98: }
99: 
100: /**
101:  * Serve a static file from the frontend directory.
102:  *
103:  * @param {string} frontendDir
104:  * @param {string} pathname
105:  * @param {import('node:http').ServerResponse} res
106:  */
107: async function serveStatic(frontendDir, pathname, res) {
108:   // Default to index.html for root
109:   const filePath = pathname === '/' || pathname === ''
110:     ? join(frontendDir, 'index.html')
111:     : join(frontendDir, pathname);
112: 
113:   try {
114:     const content = await readFile(filePath);
115:     const ext = extname(filePath);
116:     const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
117: 
118:     res.writeHead(200, {
119:       'content-type': `${mimeType}; charset=utf-8`,
120:       'content-length': content.length,
121:     });
122:     res.end(content);
123:   } catch (err) {
124:     if (err.code === 'ENOENT') {
125:       sendError(res, 404, 'NOT_FOUND', 'Not found');
126:     } else {
127:       sendError(res, 500, 'INTERNAL', 'Internal server error');
128:     }
129:   }
130: }
131: 
132: /**
133:  * Proxy a request to the backend.
134:  *
135:  * @param {string} backendUrl
136:  * @param {import('node:http').IncomingMessage} req
137:  * @param {import('node:http').ServerResponse} res
138:  * @param {string} pathname
139:  */
140: async function proxyToBackend(backendUrl, req, res, pathname) {
141:   const method = req.method ?? 'GET';
142: 
143:   // Collect request body for proxied requests with body
144:   let body = Buffer.alloc(0);
145:   if (method === 'POST' || method === 'PUT' || method === 'PATCH') {
146:     body = await collectBody(req);
147:   }
148: 
149:   const targetUrl = `${backendUrl}${pathname}${req.url?.includes('?') ? '?' + req.url.split('?')[1] : ''}`;
150: 
151:   try {
152:     const fetchOptions = {
153:       method,
154:       headers: {
155:         'content-type': req.headers['content-type'] ?? 'application/json',
156:       },
157:     };
158: 
159:     if (body.length > 0) {
160:       fetchOptions.body = body;
161:     }
162: 
163:     const backendRes = await fetch(targetUrl, fetchOptions);
164: 
165:     // Forward response headers and body
166:     res.writeHead(backendRes.status, {
167:       'content-type': backendRes.headers.get('content-type') ?? 'application/json',
168:     });
169: 
170:     const backendBody = await backendRes.text();
171:     res.end(backendBody);
172:   } catch (err) {
173:     // Backend unavailable - return deterministic 5xx JSON error
174:     sendError(res, 503, 'SERVICE_UNAVAILABLE', 'Backend service unavailable');
175:   }
176: }
177: 
178: /**
179:  * Collect the request body into a buffer.
180:  *
181:  * @param {import('node:http').IncomingMessage} req
182:  * @returns {Promise<Buffer>}
183:  */
184: function collectBody(req) {
185:   return new Promise((resolve, reject) => {
186:     const chunks = [];
187:     req.on('data', chunk => chunks.push(chunk));
188:     req.on('end', () => resolve(Buffer.concat(chunks)));
189:     req.on('error', reject);
190:   });
191: }
