103:   return new Promise((resolve, reject) => {
104:     server.on('error', reject);
105:     server.listen(port, host, () => {
106:       const address = server.address();
107:       resolve({
108:         server,
109:         port: typeof address === 'object' ? address.port : port,
110:         close: () => new Promise((done, fail) => {
111:           server.close((err) => {
112:             if (err) fail(err);
