126:  * @param {import('node:http').ServerResponse} res
127:  */
128: async function serveStatic(filePath, res) {
129:   try {
130:     const content = await readFile(filePath);
131:     const ext = extname(filePath);
132:     const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
