148: /**
149:  * Proxy a request to the backend.
150:  *
151:  * @param {string} backendUrl
152:  * @param {import('node:http').IncomingMessage} req
153:  * @param {import('node:http').ServerResponse} res
154:  * @param {string} pathname
155:  */
156: async function proxyToBackend(backendUrl, req, res, pathname) {
157:   const method = req.method ?? 'GET';
158: 
159:   // Collect request body for proxied requests with body
160:   let body = Buffer.alloc(0);
161:   if (method === 'POST' || method === 'PUT' || method === 'PATCH') {
162:     body = await collectBody(req);
163:   }
164: 
165:   const targetUrl = `${backendUrl}${pathname}${req.url?.includes('?') ? '?' + req.url.split('?')[1] : ''}`;
166: 
167:   try {
168:     const fetchOptions = {
169:       method,
170:       headers: {
171:         'content-type': req.headers['content-type'] ?? 'application/json',
172:       },
173:     };
174: 
175:     if (body.length > 0) {
176:       fetchOptions.body = body;
177:     }
178: 
179:     const backendRes = await fetch(targetUrl, fetchOptions);
180: 
181:     // Forward response headers and body
182:     res.writeHead(backendRes.status, {
183:       'content-type': backendRes.headers.get('content-type') ?? 'application/json',
184:     });
185: 
186:     const backendBody = await backendRes.text();
187:     res.end(backendBody);
188:   } catch (err) {
189:     // Backend unavailable - return deterministic 5xx JSON error
190:     sendError(res, 503, 'SERVICE_UNAVAILABLE', 'Backend service unavailable');
191:   }
192: }
193: 
194: /**
195:  * Collect the request body into a buffer.
196:  *
197:  * @param {import('node:http').IncomingMessage} req
198:  * @returns {Promise<Buffer>}
199:  */
200: function collectBody(req) {
201:   return new Promise((resolve, reject) => {
202:     const chunks = [];
203:     req.on('data', chunk => chunks.push(chunk));
204:     req.on('end', () => resolve(Buffer.concat(chunks)));
205:     req.on('error', reject);
206:   });
