215:  * @param {string} message
216:  */
217: function sendError(res, status, code, message) {
218:   const body = JSON.stringify({ error: { code, message } });
219:   res.writeHead(status, {
220:     'content-type': 'application/json; charset=utf-8',
221:     'content-length': Buffer.byteLength(body),
222:   });
223:   res.end(body);
