{"name": "write", "args": {"content": "/**
 * Unit 2 — UI API Client and State Transitions Tests
 *
 * RED phase: Tests for request helper and state management.
 *
 * These exercise the SHIPPED implementation: index.html loads only app.js,
 * whose apiRequest, context helpers and validators are the product's request
 * and state code. The real index.html + app.js are loaded into jsdom pointed
 * at a fake backend, so every assertion runs against code the browser loads.
 */

import { describe, it, before, after, beforeEach } from 'node:test';
import assert from 'node:assert';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { JSDOM } from 'jsdom';
import { FRONTEND_DIR, waitFor, tick } from './helpers/ui.mjs';

/** Load the canonical index.html + app.js into jsdom against `baseUrl`. */
async function loadApp(baseUrl) {
  const html = await readFile(join(FRONTEND_DIR, 'index.html'), 'utf8');
  const appSource = await readFile(join(FRONTEND_DIR, 'app.js'), 'utf8');

  const dom = new JSDOM(html, {
    url: `${baseUrl}/`,
    runScripts: 'outside-only',
    pretendToBeVisual: true,
  });
  const win = dom.window;

  const requests = [];
  win.fetch = async (input, init = {}) => {
    const url = typeof input === 'string' ? new URL(input, baseUrl) : new URL(input.url ?? input);
    let body = init.body;
    if (body !== undefined && typeof body !== 'string') body = String(body);
    const response = await globalThis.fetch(url, init);
    requests.push({
      method: init.method ?? 'GET',
      url: url.pathname + url.search,
      body,
      status: response.status,
    });
    return response;
  };

  if (typeof win.crypto?.randomUUID !== 'function') {
    Object.defineProperty(win, 'crypto', {
      value: {
        randomUUID: () => globalThis.crypto.randomUUID(),
        getRandomValues: (a) => globalThis.crypto.getRandomValues(a),
      },
      configurable: true,
    });
  }
  if (typeof win.matchMedia !== 'function') {
    win.matchMedia = () => ({ matches: false, addListener() {}, removeListener() {} });
  }

  // Plain script: function declarations land on the window; init() runs on
  // DOMContentLoaded (or immediately once parsing has finished).
  win.eval(appSource);

  await waitFor(
    () => {
      const status = win.document.getElementById('connection-status');
      return (
        status !== null &&
        (status.classList.contains('checking') ||
          status.classList.contains('connected') ||
          status.classList.contains('unavailable'))
      );
    },
    { label: 'app init (connection status marked)' },
  );
  await tick(win, 30);

  return {
    window: win,
    document: win.document,
    requests,
    close: () => win.close(),
  };
}

describe('Unit 2: UI API Client and State Transitions', () => {
  /** @type {import('node:http').Server} */
  let fakeBackend;
  let baseUrl;
  /** @type {Awaited<ReturnType<typeof loadApp>>} */
  let app;

  before(async () => {
    // Create fake backend
    fakeBackend = createServer((req, res) => {
      let body = '';
      req.on('data', chunk => body += chunk);
      req.on('end', () => {
        const parsedBody = body ? JSON.parse(body) : null;

        if (req.url === '/health') {
          res.writeHead(200, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ status: 'ok' }));
        } else if (req.url === '/v1/restaurants' && req.method === 'POST') {
          res.writeHead(201, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ id: 'rest-123', name: parsedBody.name, timezone: parsedBody.timezone }));
        } else if (req.url.startsWith('/v1/bookings') && req.method === 'POST') {
          // Replayed idempotency key answers 200; a fresh one answers 201.
          const existing = parsedBody.idempotency_key === 'duplicate-key';
          res.writeHead(existing ? 200 : 201, { 'content-type': 'application/json' });
          res.end(JSON.stringify({
            id: 'booking-456',
            restaurant_id: parsedBody.restaurant_id,
            table_ids: parsedBody.table_ids,
            party_size: parsedBody.party_size,
            start_utc: '2026-10-04T19:00:00Z',
            duration_min: parsedBody.duration_min,
            status: 'confirmed',
            created_at_utc: '2026-10-04T12:00:00Z',
          }));
        } else if (req.url === '/v1/bookings/booking-456' && req.method === 'GET') {
          res.writeHead(200, { 'content-type': 'application/json' });
          res.end(JSON.stringify({
            id: 'booking-456',
            restaurant_id: 'rest-123',
            table_ids: ['table-2'],
            party_size: 2,
            start_utc: '2026-10-04T19:00:00Z',
            duration_min: 60,
            status: 'confirmed',
            created_at_utc: '2026-10-04T12:00:00Z',
          }));
        } else if (req.url === '/v1/bookings/booking-456' && req.method === 'DELETE') {
          res.writeHead(204);
          res.end();
        } else if (req.url.startsWith('/v1/restaurants/bad-slots/availability') && req.method === 'GET') {
          // Well-formed JSON whose slots field is not a list: exercises the
          // shipped MALFORMED_RESPONSE render path.
          res.writeHead(200, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ slots: 'not-a-list' }));
        } else if (req.url.startsWith('/v1/restaurants/rest-123/availability') && req.method === 'GET') {
          res.writeHead(200, { 'content-type': 'application/json' });
          res.end(JSON.stringify({
            slots: [
              { start_utc: '2026-10-04T18:00:00Z', start_local: '2026-10-04T14:00', table_ids: ['table-2', 'table-4'] },
              { start_utc: '2026-10-04T19:00:00Z', start_local: '2026-10-04T15:00', table_ids: ['table-2', 'table-4'] },
            ]
          }));
        } else if (req.url === '/v1/error') {
          res.writeHead(409, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ error: { code: 'SLOT_TAKEN', message: 'Slot is already booked' } }));
        } else if (req.url === '/v1/malformed') {
          res.writeHead(200, { 'content-type': 'application/json' });
          res.end('this is not json');
        } else {
          res.writeHead(404, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ error: { code: 'NOT_FOUND', message: 'Not found' } }));
        }
      });
    });

    await new Promise((resolve) => {
      fakeBackend.listen(0, '127.0.0.1', () => {
        baseUrl = `http://127.0.0.1:${fakeBackend.address().port}`;
        resolve();
      });
    });

    app = await loadApp(baseUrl);
  });

  after(async () => {
    app.close();
    await new Promise((resolve) => fakeBackend.close(resolve));
  });

  beforeEach(() => {
    // Each block starts from a clean session state.
    app.window.eval('clearContext();');
    app.requests.length = 0;
  });

  describe('API Request Helper', () => {
    it('handles JSON success responses', async () => {
      const result = await app.window.apiRequest(`${baseUrl}/health`);
      assert.strictEqual(result.ok, true);
      assert.strictEqual(result.status, 200);
      assert.deepStrictEqual(result.data, { status: 'ok' });
    });

    it('handles 204 success with no content', async () => {
