1: /**
2:  * Connection, pragmas, migration, and the write transaction every mutating path
3:  * goes through.
4:  *
5:  * Two rules live here and nowhere else:
6:  *   - every connection is WAL with a busy timeout, so separate OS processes can
7:  *     write the same file concurrently without either one inventing a failure;
8:  *   - every write runs inside BEGIN IMMEDIATE, so the read-then-write sequence in
9:  *     bookings.ts is serialised by the database rather than by anything in this
10:  *     process.
11:  */
12: 
13: import { DatabaseSync } from 'node:sqlite';
14: import { readFileSync } from 'node:fs';
15: import { fileURLToPath } from 'node:url';
16: import { isBusyError } from './errors.ts';
17: 
18: export type Db = DatabaseSync;
19: 
20: const SCHEMA_FILE = fileURLToPath(new URL('./schema.sql', import.meta.url));
21: const MIGRATION_NAME = '0001_booking_core';
22: 
23: const DEFAULT_BUSY_TIMEOUT_MS = 5000;
24: const DEFAULT_BUSY_ATTEMPTS = 3;
25: const DEFAULT_BUSY_BACKOFF_MS = 20;
26: 
27: export type OpenOptions = {
28:   /** Overrides the 5000 ms default. Only the busy-path test needs a shorter wait. */
29:   busyTimeoutMs?: number;
30: };
31: 
32: export type TxOptions = {
33:   /** Attempts on SQLITE_BUSY before the caller is told to retry. */
34:   busyAttempts?: number;
35:   busyBackoffMs?: number;
36: };
37: 
38: export function openDatabase(path: string, options: OpenOptions = {}): Db {
39:   const busyTimeoutMs = options.busyTimeoutMs ?? DEFAULT_BUSY_TIMEOUT_MS;
40:   if (!Number.isInteger(busyTimeoutMs) || busyTimeoutMs < 0) {
41:     throw new TypeError(`busyTimeoutMs must be a non-negative integer, got ${String(busyTimeoutMs)}`);
42:   }
43:   const db = new DatabaseSync(path);
44:   db.exec(`PRAGMA busy_timeout = ${busyTimeoutMs}`);
45:   // Switching journal_mode to WAL takes a brief exclusive lock, and busy_timeout does
46:   // NOT make that wait: when several processes open the same fresh file at once the
47:   // losers get a plain SQLITE_BUSY out of a connection that has done nothing wrong. Retry
48:   // the switch itself, then the migration, so a cold start is safe for every opener.
49:   retryWhileBusy(() => db.exec('PRAGMA journal_mode = WAL'));
50:   db.exec('PRAGMA foreign_keys = ON');
51:   migrate(db);
52:   return db;
53: }
54: 
55: /** Run `fn`, retrying the bounded number of times while SQLite reports ordinary contention. */
56: function retryWhileBusy(fn: () => void): void {
57:   for (let attempt = 1; ; attempt += 1) {
58:     try {
59:       fn();
60:       return;
61:     } catch (err) {
62:       if (!isBusyError(err) || attempt >= DEFAULT_BUSY_ATTEMPTS) throw err;
63:       sleepSync(DEFAULT_BUSY_BACKOFF_MS * attempt);
64:     }
65:   }
66: }
67: 
68: export function closeDatabase(db: Db): void {
69:   db.close();
70: }
71: 
72: function migrationApplied(db: Db, name: string): boolean {
73:   const ledger = db
74:     .prepare("SELECT 1 AS present FROM sqlite_master WHERE type = 'table' AND name = 'schema_migration'")
75:     .get();
76:   if (ledger === undefined) return false;
77:   return db.prepare('SELECT 1 AS present FROM schema_migration WHERE name = ?').get(name) !== undefined;
78: }
