1: /**
2:  * Stage 4 Static Server and Proxy
3:  *
4:  * Serves static files from the frontend directory and proxies API requests
5:  * to the backend service.
6:  */
7: 
8: import { createServer } from 'node:http';
9: import { readFile } from 'node:fs/promises';
10: import { join, resolve, extname, sep } from 'node:path';
11: import { fileURLToPath } from 'node:url';
12: 
13: export const DEFAULT_BACKEND_URL = 'http://127.0.0.1:3000';
14: 
15: /**
16:  * Resolve a raw request path (query/fragment stripped, NOT URL-normalized)
17:  * against the frontend directory, refusing anything that escapes it.
18:  *
19:  * The guard runs on the raw path so `..` segments reach it: the WHATWG URL
20:  * parser would otherwise collapse them before the check and the guard could
21:  * never fire. Returns the absolute file path, or null when the request tries
22:  * to leave the frontend directory (including sibling-prefix tricks such as
23:  * `frontend-secret/` next to `frontend/`).
24:  */
25: export function resolveStaticPath(frontendDir, rawPath) {
26:   const candidate = resolve(join(frontendDir, rawPath));
27:   const root = frontendDir.endsWith(sep) ? frontendDir : frontendDir + sep;
28:   if (candidate !== frontendDir && !candidate.startsWith(root)) {
29:     return null;
30:   }
31:   return candidate;
32: }
33: 
34: const MIME_TYPES = {
35:   '.html': 'text/html',
36:   '.js': 'application/javascript',
37:   '.css': 'text/css',
38:   '.json': 'application/json',
39:   '.png': 'image/png',
40:   '.jpg': 'image/jpeg',
41:   '.gif': 'image/gif',
42:   '.svg': 'image/svg+xml',
43:   '.ico': 'image/x-icon',
44: };
