46: /**
47:  * @typedef {Object} ServerOptions
48:  * @property {number} [port=8080]
49:  * @property {string} [host='127.0.0.1']
50:  * @property {string} [backendUrl]
51:  * @property {(id: string) => Promise<void>} [onRestaurantCreated]
52:  *   Optional composition-layer hook (TASK.md section 9, R3): awaited after a
53:  *   buffered 201 from proxied `POST /v1/restaurants`, before the backend's
54:  *   response is forwarded unchanged. This file contains no SQL and no
55:  *   database imports; fixture preparation lives in deploy/demo.mjs. Absent
56:  *   hook (standalone run) means no fixture preparation.
57:  */
58: 
59: /**
60:  * @typedef {Object} ServerInstance
61:  * @property {import('node:http').Server} server
62:  * @property {number} port
63:  * @property {() => Promise<void>} close
64:  */
65: 
66: /**
67:  * Start the Stage 4 static server and proxy.
68:  *
69:  * @param {string} frontendDir - Directory containing static files
70:  * @param {ServerOptions} options
71:  * @returns {Promise<ServerInstance>}
72:  */
73: export async function startServer(frontendDir, options = {}) {
74:   const port = options.port ?? 8080;
75:   const host = options.host ?? '127.0.0.1';
76:   const backendUrl = options.backendUrl ?? DEFAULT_BACKEND_URL;
77:   const onRestaurantCreated = options.onRestaurantCreated;
78:   const root = resolve(frontendDir);
79: 
80:   const server = createServer(async (req, res) => {
81:     // Raw target: query/fragment stripped, no dot-segment normalization.
82:     const rawPath = (req.url ?? '/').split(/[?#]/)[0] || '/';
83: 
84:     // Block path traversal attempts before anything normalizes them away.
85:     const resolvedPath = resolveStaticPath(root, rawPath);
86:     if (resolvedPath === null) {
87:       sendError(res, 404, 'NOT_FOUND', 'Not found');
88:       return;
89:     }
90: 
91:     let pathname;
92:     try {
93:       pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
94:     } catch {
95:       sendError(res, 400, 'BAD_REQUEST', 'Invalid URL');
96:       return;
97:     }
98: 
99:     // API routes go to backend
100:     if (pathname.startsWith('/v1/') || pathname === '/health') {
101:       await proxyToBackend(backendUrl, req, res, pathname, onRestaurantCreated);
102:       return;
103:     }
104: 
105:     // Static file serving: the root itself serves index.html.
106:     const filePath = resolvedPath === root ? join(root, 'index.html') : resolvedPath;
107:     await serveStatic(filePath, res);
108:   });
109: 
110:   return new Promise((resolve, reject) => {
111:     server.on('error', reject);
112:     server.listen(port, host, () => {
113:       const address = server.address();
114:       resolve({
115:         server,
116:         port: typeof address === 'object' ? address.port : port,
117:         close: () => new Promise((done, fail) => {
118:           server.close((err) => {
119:             if (err) fail(err);
120:             else done();
121:           });
122:           server.closeAllConnections();
123:         }),
124:       });
125:     });
126:   });
127: }
