129: /**
130:  * Serve a static file given its already-resolved absolute path.
131:  *
132:  * @param {string} filePath
133:  * @param {import('node:http').ServerResponse} res
134:  */
135: async function serveStatic(filePath, res) {
136:   try {
137:     const content = await readFile(filePath);
138:     const ext = extname(filePath);
139:     const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
140: 
141:     res.writeHead(200, {
142:       'content-type': `${mimeType}; charset=utf-8`,
143:       'content-length': content.length,
144:     });
145:     res.end(content);
146:   } catch (err) {
147:     if (err.code === 'ENOENT') {
148:       sendError(res, 404, 'NOT_FOUND', 'Not found');
149:     } else {
150:       sendError(res, 500, 'INTERNAL', 'Internal server error');
151:     }
152:   }
153: }
154: 
155: /**
156:  * Proxy a request to the backend.
157:  *
158:  * @param {string} backendUrl
159:  * @param {import('node:http').IncomingMessage} req
160:  * @param {import('node:http').ServerResponse} res
161:  * @param {string} pathname
162:  * @param {(id: string) => Promise<void>} [onRestaurantCreated]
163:  */
164: async function proxyToBackend(backendUrl, req, res, pathname, onRestaurantCreated) {
165:   const method = req.method ?? 'GET';
166: 
167:   // Collect request body for proxied requests with body
168:   let body = Buffer.alloc(0);
169:   if (method === 'POST' || method === 'PUT' || method === 'PATCH') {
170:     body = await collectBody(req);
171:   }
172: 
173:   const targetUrl = `${backendUrl}${pathname}${req.url?.includes('?') ? '?' + req.url.split('?')[1] : ''}`;
174: 
175:   try {
176:     const fetchOptions = {
177:       method,
178:       headers: {
179:         'content-type': req.headers['content-type'] ?? 'application/json',
180:       },
181:     };
182: 
183:     if (body.length > 0) {
184:       fetchOptions.body = body;
185:     }
186: 
187:     const backendRes = await fetch(targetUrl, fetchOptions);
188:     const backendBody = await backendRes.text();
189: 
190:     // R3 composition hook: run after the response is buffered, before it is
191:     // forwarded. Failures are logged; the backend's 201 is still forwarded.
192:     if (
193:       typeof onRestaurantCreated === 'function' &&
194:       method === 'POST' &&
195:       pathname === '/v1/restaurants' &&
196:       backendRes.status === 201
197:     ) {
198:       try {
199:         const created = JSON.parse(backendBody);
200:         if (typeof created?.id === 'string' && created.id !== '') {
201:           await onRestaurantCreated(created.id);
202:         }
203:       } catch (err) {
204:         console.error(`[frontend] onRestaurantCreated hook failed: ${err?.message ?? err}`);
205:       }
206:     }
207: 
208:     // Forward response headers and body
209:     res.writeHead(backendRes.status, {
210:       'content-type': backendRes.headers.get('content-type') ?? 'application/json',
211:     });
212:     res.end(backendBody);
213:   } catch (err) {
214:     // Backend unavailable - return deterministic 5xx JSON error
215:     sendError(res, 503, 'SERVICE_UNAVAILABLE', 'Backend service unavailable');
216:   }
217: }
218: 
219: /**
220:  * Collect the request body into a buffer.
221:  *
222:  * @param {import('node:http').IncomingMessage} req
223:  * @returns {Promise<Buffer>}
224:  */
225: function collectBody(req) {
226:   return new Promise((resolve, reject) => {
227:     const chunks = [];
228:     req.on('data', chunk => chunks.push(chunk));
229:     req.on('end', () => resolve(Buffer.concat(chunks)));
230:     req.on('error', reject);
231:   });
232: }
