234: /**
235:  * Send a JSON error response.
236:  *
237:  * @param {import('node:http').ServerResponse} res
238:  * @param {number} status
239:  * @param {string} code
240:  * @param {string} message
241:  */
242: function sendError(res, status, code, message) {
243:   const body = JSON.stringify({ error: { code, message } });
244:   res.writeHead(status, {
245:     'content-type': 'application/json; charset=utf-8',
246:     'content-length': Buffer.byteLength(body),
247:   });
248:   res.end(body);
249: }
