{"name": "write", "args": {"content": "import { get as httpGet } from 'node:http';
const base = new URL(process.argv[2]);
const port = Number(base.port);
const out = {};

const j = async (path) => {
  const r = await fetch(base.origin + path);
  const t = await r.text();
  return { status: r.status, len: t.length, head: t.slice(0, 40).replace(/\s+/g, ' ') };
};

const rawGet = (path) =>
  new Promise((resolve) => {
    const req = httpGet({ hostname: '127.0.0.1', port, path }, (res) => {
      let body = '';
      res.on('data', (c) => (body += c));
      res.on('end', () => resolve({ status: res.statusCode, body }));
    });
    req.on('error', (e) => resolve({ error: String(e) }));
  });

out['GET /index.html'] = await j('/index.html');
out['GET /styles.css'] = await j('/styles.css');
out['GET /app.js'] = await j('/app.js');
out['GET / (root)'] = await j('/');
out['GET /health (proxied)'] = await j('/health');
out['GET /v1/restaurants (proxied)'] = await j('/v1/restaurants');
out['raw GET /../plan.md'] = await rawGet('/../plan.md');
out['raw GET /..\\plan.md'] = await rawGet('/..\\plan.md');
out['raw GET /%2e%2e/plan.md'] = await rawGet('/%2e%2e/plan.md');
const leak = Object.entries(out).filter(
  ([, v]) => v && typeof v === 'object' && typeof v.body === 'string' && /dark-factory|Reviewer|plan\b/i.test(v.body),
);
out.leaked_foreign_content = leak.map(([k]) => k);
